<?php use AlbaTech\Core\View; ?>
<div class="admin-page-actions"><p>Manage products and client case studies shown on the public website.</p><a class="button button--primary" href="/admin/work/create"><i class="fa-solid fa-plus" aria-hidden="true"></i> Add entry</a></div>
<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Entry</th><th>Type</th><th>Category</th><th>Order</th><th>Status</th><th>Homepage</th><th>Actions</th></tr></thead><tbody>
<?php if (empty($projects)): ?><tr><td colspan="7">No entries yet. Add a product or client case study to start building the portfolio.</td></tr><?php endif; ?>
<?php foreach ($projects as $project): $publicBase = ($project['kind'] ?? 'project') === 'product' ? '/products/' : '/work/'; ?><tr><td><div class="work-admin-project"><?php if (!empty($project['cover_image'])): ?><img src="/<?= View::escape(ltrim($project['cover_image'],'/')) ?>" alt="" loading="lazy"><?php endif; ?><div><strong><?= View::escape($project['title']) ?></strong><small><?= View::escape($publicBase) ?><?= View::escape($project['slug']) ?></small></div></div></td><td><?= ($project['kind'] ?? 'project') === 'product' ? 'Product' : 'Case study' ?><br><small><?= View::escape(ucfirst(str_replace('_', ' ', (string) ($project['lifecycle_status'] ?? 'live')))) ?></small></td><td><?= View::escape($project['category_name']) ?></td><td><?= (int)$project['sort_order'] ?></td><td><span class="status-pill status-pill--<?= View::escape($project['status']) ?>"><?= View::escape(ucfirst($project['status'])) ?></span></td><td><?= (int)$project['is_featured']===1?'Featured':'No' ?></td><td><div class="table-actions"><a class="button button--small button--secondary" href="/admin/work/<?= (int)$project['id'] ?>/edit">Edit</a><?php if ($project['status']==='published'): ?><a class="button button--small button--secondary" href="<?= View::escape($publicBase) ?><?= rawurlencode($project['slug']) ?>" target="_blank" rel="noopener">View</a><?php endif; ?><form method="post" action="/admin/work/<?= (int)$project['id'] ?>/delete" data-confirm="Delete this entry and its cover image?"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><button class="button button--small button--danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?>
</tbody></table></div>
